from common import *
P=R/'projects/game-math-interpolation-paths-v2';H=P/'production/concept-fit-v2';T=read(H/'timeline.json');D=P/'publishing/revisions/concept-fit-v2';D.mkdir(parents=True,exist_ok=True)
en=['From orientation operations to interpolation','Intermediate orientations, paths and speed','A cabinet door between closed and open','Can mixing four numbers produce an orientation?','What a rotation interpolation must preserve','Choosing the quaternion sign and the shorter path','Why opposite signs can describe the same orientation','A fixed hinge isolates the turning door','The same endpoint can hide a different rotation history','From a straight blend to a spherical path','Spherical linear interpolation','Physical size versus unit quaternion length','From the formula to intermediate values','Normalized linear interpolation','A second hinged door and its intermediate orientations','Divide a90-degree rotation into four intervals','Computing quarter and halfway orientations','Handling very small angle differences','Same path, different arrival times','Open angle and angular speed','From angular speed to the time function','Choosing a time function','Substitute numbers in a time function','From two orientations to several keys','Joining several orientation keys','One extra revolution, the same final orientation','Observe the object’s front and up directions','Why one direction cannot determine orientation','What to check before using interpolation','From interpolation to representation conversion']
assert len(en)==len(T['scenes'])
def stamp(t):n=int(t);return f'{n//60:02}:{n%60:02}'
for lang in ['ko','en']:
 old=(P/f'publishing/upload-description.{lang}.txt').read_text(encoding='utf8');footer='🎮'+old.split('🎮',1)[1]
 intro='경첩을 중심으로 열리는 문을 보며 두 자세 사이의 중간 자세를 살펴봅니다. 같은 끝 자세와 회전 이력, 쿼터니언 부호 선택, 구면 선형 보간과 정규화 선형 보간, 각속도와 시간 함수를 기존 강의 순서대로 계산합니다.' if lang=='ko' else 'Observe hinged doors to understand orientations between two endpoints. Following the original lesson order, compare endpoint orientation and motion history, quaternion sign selection, spherical and normalized linear interpolation, angular speed and time functions.'
 note='실제 게임 화면과 자체 계산 모형은 구분해 표시합니다. 게임 내부의 보간 함수나 회전각을 추정한 값은 사용하지 않습니다. 별도 배경음악은 추가하지 않았습니다.' if lang=='ko' else 'Actual game footage and our mathematical models are labeled separately. We do not claim to measure the game’s internal interpolation function or rotation angles. No separate background-music track was added.'
 chapters='\n'.join(stamp(0 if i==0 else s['start'])+' '+(s['title'] if lang=='ko' else en[i]) for i,s in enumerate(T['scenes']))
 credits='\n\n'+('게임 화면 출처·권리' if lang=='ko' else 'Gameplay sources and rights')+'\nEscape Simulator — Pine Studio. Official public press kit, developer-created level-editor footage for contextual game coverage.\nhttps://docs.escapesimulator.com/docs/press\nhttps://drive.google.com/file/d/1kBroCcuJ24P7dHbf-FvEZDeWOWW1-ln-/view\n'
 (D/f'upload-description.{lang}.txt').write_text(intro+'\n\n'+note+'\n\n'+('챕터' if lang=='ko' else 'Chapters')+'\n'+chapters+'\n'+stamp(T['seconds']-10)+' '+('멤버십 감사와 코칭 안내' if lang=='ko' else 'Membership thanks and programming coaching')+'\n\n'+footer.rstrip()+credits,encoding='utf8')
save(H/'description-drafts.json',dict(status='local drafts only',files=[dict(path=rel(x),sha256=sha(x)) for x in D.glob('*.txt')],creditsAtBottom=True,uploadAuthorized=False))
